import pandas as pd
import numpy as np

# Load the datasets
gas_waste_data = pd.read_csv('chunks_csv/bivariate/bivariate_2021_gas_waste.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Data Validation: Check for missing values
if gas_waste_data.isnull().any().any() or adjacency_data.isnull().any().any():
    raise ValueError("Missing values detected in the datasets.")

# Create a mapping of each borough to its neighboring boroughs
neighbors = {}
for _, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors:
        neighbors[borough] = []
    neighbors[borough].append(neighbor)

# Calculate Lee's L Statistic
def calculate_lees_l(gas_values, waste_values):
    mean_gas = np.mean(gas_values)
    mean_waste = np.mean(waste_values)
    return np.sum((gas_values - mean_gas) * (waste_values - mean_waste)) / (len(gas_values) - 1)

# Observed Lee's L statistic
observed_l = []
for borough, gas_value in zip(gas_waste_data['borough'], gas_waste_data['Gas_value']):
    if borough in neighbors:
        neighbor_waste_values = gas_waste_data[gas_waste_data['borough'].isin(neighbors[borough])]['Waste_value']
        if not neighbor_waste_values.empty:
            observed_l.append(calculate_lees_l(np.array([gas_value]), neighbor_waste_values.to_numpy()))

observed_l_statistic = np.mean(observed_l)

# Perform Randomization Test
n_permutations = 500
random_l_statistics = []

for _ in range(n_permutations):
    shuffled_waste_values = np.random.permutation(gas_waste_data['Waste_value'].to_numpy())
    random_l = []
    for borough, gas_value in zip(gas_waste_data['borough'], gas_waste_data['Gas_value']):
        if borough in neighbors:
            neighbor_waste_values = shuffled_waste_values[gas_waste_data['borough'].isin(neighbors[borough])]
            if neighbor_waste_values.size > 0:
                random_l.append(calculate_lees_l(np.array([gas_value]), neighbor_waste_values))
    random_l_statistics.append(np.mean(random_l))

# Calculate p-value
p_value = np.sum(np.array(random_l_statistics) >= observed_l_statistic) / n_permutations

# Determine significance
data_points_used = len(observed_l)
if p_value < 0.05:
    if observed_l_statistic > 0:
        verdict = "POSITIVE"
    else:
        verdict = "NEGATIVE"
else:
    verdict = "NOT SIGNIFICANT"

# Print results
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {verdict} (test statistic = {observed_l_statistic}, p = {p_value})")

import pandas as pd
import numpy as np

# Load the datasets
gas_waste_data = pd.read_csv('chunks_csv/bivariate/bivariate_2021_gas_waste.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Data Validation: Confirm no missing values
assert gas_waste_data.isnull().sum().sum() == 0, "Missing values detected in gas and waste data."

# Create a mapping of each borough to its neighboring boroughs
neighbors = {}
for _, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors:
        neighbors[borough] = []
    neighbors[borough].append(neighbor)

# Function to calculate Lee's L statistic
def calculate_lees_l(gas_value, waste_values):
    mean_waste = np.mean(waste_values)
    return np.sum((gas_value - mean_waste) * (waste_values - mean_waste))

# Calculate the observed Lee's L statistic
observed_l = 0
for borough, gas_value in zip(gas_waste_data['borough'], gas_waste_data['Gas_value']):
    if borough in neighbors:
        neighbor_waste_values = gas_waste_data[gas_waste_data['borough'].isin(neighbors[borough])]['Waste_value']
        if not neighbor_waste_values.empty:
            observed_l += calculate_lees_l(gas_value, neighbor_waste_values)

# Permutation test
n_permutations = 500
permuted_l_statistics = []
for _ in range(n_permutations):
    permuted_waste_values = np.random.permutation(gas_waste_data['Waste_value'].values)
    permuted_l = 0
    for borough, gas_value in zip(gas_waste_data['borough'], gas_waste_data['Gas_value']):
        if borough in neighbors:
            neighbor_waste_values = permuted_waste_values[gas_waste_data['borough'].isin(neighbors[borough])]
            if neighbor_waste_values.size > 0:
                permuted_l += calculate_lees_l(gas_value, neighbor_waste_values)
    permuted_l_statistics.append(permuted_l)

# Calculate p-value
permuted_l_statistics = np.array(permuted_l_statistics)
p_value = np.sum(permuted_l_statistics >= observed_l) / n_permutations

# Determine significance
data_points_used = len(gas_waste_data)
if p_value < 0.05:
    if observed_l > 0:
        verdict = "POSITIVE"
    else:
        verdict = "NEGATIVE"
else:
    verdict = "NOT SIGNIFICANT"

# Print results
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {verdict} (test statistic = {observed_l}, p = {p_value})")
